window.AUTH=window.AUTH||{};window.AUTH["23-824"]={"d":"23-824","id":"2024/23-824","n":"United States v. Miller","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2024-08-08","url":"https://www.supremecourt.gov/DocketPDF/23/23-824/322075/20240808212316792_23-824tsUnitedStates.pdf","side":"pet","n":71},{"k":"respondent","label":"Brief of respondent David L. Miller","date":"2024-09-19","url":"https://www.supremecourt.gov/DocketPDF/23/23-824/326364/20240919142905852_Miller%20Merits%20Brief.pdf","side":"res","n":73},{"k":"reply","label":"Reply of petitioner United States","date":"2024-10-21","url":"https://www.supremecourt.gov/DocketPDF/23/23-824/328852/20241021163829249_23-824rbUnitedStates.pdf","side":"pet","n":59}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us2r21_6kh7.pdf","tr":true,"items":[{"t":"case","label":"Acequia, Inc. v. Clinton (In re Acequia, Inc.)","cite":"34 F.3d 800","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/34/800/","by":{"0":"17"}},{"t":"case","label":"Begier v. IRS","cite":"496 U.S. 53","y":1990,"id":"1989/89-393","sc":1,"sum":"AIA's trust-fund tax payments from its general accounts were transfers of property held in trust and therefore cannot be avoided as preferences.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Bull v. United States","cite":"295 U.S. 247","y":1935,"id":"scdb/1934-123","sc":1,"sum":"'(1) That the taxpayer was entitled to recoup from the amount of the income tax the amount of the unlawful estate tax by suit for the difference in the Court of Claims, although suit to recover the unlawful tax independently had become barred. Pp. 261-262. (2) A complaint by which the taxpayer prayed judgment in the alternative, either for the amount of the income tax or for what should have been credited against it …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Coventry Health Care of Mo., Inc. v. Nevils","cite":"581 U.S. 87","y":2017,"id":"2016/16-149","sc":1,"sum":"The Court determined that the Federal Employees Health Benefits Act (FEHBA) preempts state laws that prohibit insurance companies from claiming the proceeds of personal injury settlements pursuant to their contracts, and the express preemption clause of the FEHBA does not violate the Supremacy Clause.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Davis v. Willey","cite":"263 F. 588","y":1920,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F./263/588/","op":1,"by":{"0":"16","2":"22"}},{"t":"case","label":"Department of Agric. Rural Dev. Rural Hous. Serv. v. Kirtz","cite":"601 U.S. 42","y":2024,"id":"2023/22-846","sc":1,"op":2,"sum":"A consumer may sue a federal agency under 15 U. S. C. §§1681n and 1681o for defying the terms of the Fair Credit Reporting Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"33","1":"10, 13, 27, 27","2":"7, 12"}},{"t":"case","label":"Ebner v. Kaiser (In re Kaiser)","cite":"525 B.R. 697","y":2014,"court":"Bankr. N.D. Ill.","url":"https://www.courtlistener.com/c/B.R./525/697/","by":{"0":"13"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"op":2,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"0":"33, 34"}},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"op":3,"sum":"After the Federal Savings and Loan Insurance Corporation (FSLIC), as receiver for a failing thrift institution, terminated respondent Meyer from his job as a senior officer of that institution, he filed this suit in the District Court, claiming that his summary discharge deprived him of a property right without due process of law in violation of the Fifth Amendment. In making this claim, he relied on Bivens v. Six …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10, 20, 33","1":"27-28"}},{"t":"case","label":"Hoffman v. Connecticut Dep’t of Income Maint.","cite":"492 U.S. 96","y":1989,"id":"1988/88-412","sc":1,"op":1,"ar":2,"sum":"The judgment is affirmed. 850 F. 2d 50, affirmed. JUSTICE WHITE, joined by THE CHIEF JUSTICE, JUSTICE O'CONNOR, and JUSTICE KENNEDY, concluded that in enacting § 106(c) Congress did not abrogate the Eleventh Amendment immunity of the States. Congress has not made an intention to abrogate unmistakably clear in the provision's language. The narrow scope of the waivers of sovereign immunity as to certain particular …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31, 32","1":"31-32"}},{"t":"case","label":"Kurns v. Railroad Friction Prods. Corp.","cite":"565 U.S. 625","y":2012,"id":"2011/10-879","sc":1,"sum":"The Court held that the Locomotive Inspection Act preempts state law design defect claims and state law failure to warn claims.","sumSrc":"Oyez","by":{"0":"36","1":"47"}},{"t":"case","label":"Lac du Flambeau Band of Lake Superior Chippewa Indians v. Coughlin","cite":"599 U.S. 382","y":2023,"id":"2022/22-227","sc":1,"sum":"The Bankruptcy Code unequivocally abrogates the sovereign immunity of all governments, including federally recognized Indian tribes.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"33","1":"24-25, 41, 43"}},{"t":"case","label":"Lamar, Archer & Cofrin, LLP v. Appling","cite":"584 U.S. 709","y":2018,"id":"2017/16-1215","sc":1,"op":1,"sum":"The Court decided that a statement regarding a specific asset can be a “statement respecting the debtor’s . . . financial condition” under section 523(a)(2)(B) of the Bankruptcy Code.","sumSrc":"Oyez","by":{"0":"8, 26, 28","1":"8, 15-17, 42","2":"5, 6"}},{"t":"case","label":"Mendelsohn v. Kovalchuk (In re APCO Merch. Servs., Inc.)","cite":"585 B.R. 306","y":2018,"court":"Bankr. E.D.N.Y.","url":"https://www.courtlistener.com/c/B.R./585/306/","by":{"0":"4"}},{"t":"case","label":"Merit Mgmt. Grp., LP v. FTI Consulting, Inc.","cite":"583 U.S. 366","y":2018,"id":"2017/16-784","sc":1,"sum":"The Court held that the safe harbor provision of 11 U.S.C. § 546(e), which prohibits a trustee from avoiding a transfer made by or to a financial institution, does not include transfers where the benefit and detriment of the transfer impact companies that are not financial institutions.","sumSrc":"Oyez","by":{"0":"2, 3","1":"4, 40-41"}},{"t":"case","label":"Muldrow v. City of St. Louis","cite":"144 S. Ct. 967","y":2024,"id":"2023/22-193","sc":1,"sum":"An employee challenging a job transfer under Title VII must show that the transfer brought about some harm with respect to an identifiable term or condition of employment, but that harm need not be significant.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25","1":"34"}},{"t":"case","label":"Office of Pers. Mgmt. v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"sum":"The Court held that the Appropriations Clause of the Constitution explicitly states that no money can be paid from the Treasury unless specifically authorized by a statute. Since there is a statute that denies Richmond his benefits, and there is not one that provides an exception, the Court held that Richmond’s receipt of incorrect information cannot affect the non-payment of his benefits.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Pattern Makers’ League of N. Am. v. NLRB","cite":"473 U.S. 95","y":1985,"id":"1984/83-1894","sc":1,"sum":"In related cases this Court has invariably yielded to Board decisions on whether fines imposed by a union \"restrained or coerced\" employees. Moreover, the Board has consistently construed § 8(b)(1)(A) as prohibiting the fining of employees who have resigned from a union contrary to a restriction in the union constitution. Therefore, the Board's decision in this case is entitled to this Court's deference.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27","1":"18","2":"5"}},{"t":"case","label":"Patterson v. Shumate","cite":"504 U.S. 753","y":1992,"id":"1991/91-913","sc":1,"sum":"The plain language of the Bankruptcy Code and ERISA establishes that an antialienation provision in a qualified pension plan constitutes a restriction on transfer enforceable under \"applicable nonbankruptcy law\" for purposes of § 541(c)(2).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3"}},{"t":"case","label":"Presley v. Etowah Cnty. Comm’n","cite":"502 U.S. 491","y":1992,"id":"1991/90-711","sc":1,"op":1,"sum":"Rejecting a broad reading of the phrase “ `with respect to voting' ” in the Voting Rights Act where doing so “would work an unconstrained expansion of its coverage”.","sumSrc":"opinion","by":{"0":"26","1":"18","2":"6"}},{"t":"case","label":"Sender v. Simon","cite":"84 F.3d 1299","y":1996,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/84/1299/","by":{"0":"3, 14"}},{"t":"case","label":"Sigmon v. Southwest Airlines Co.","cite":"110 F.3d 1200","y":1997,"url":"https://www.courtlistener.com/c/F.3d/110/1200/","by":{"0":"36"}},{"t":"case","label":"The Official Comm. of Unsecured Creditors of Cybergenics Corp. v. Chinery (In re Cybergenics Corp.)","cite":"226 F.3d 237","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/226/237/","by":{"0":"15"}},{"t":"case","label":"Umland v. PLANCO Fin. Servs., Inc.","cite":"542 F.3d 59","y":2008,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/542/59/","by":{"0":"36"}},{"t":"case","label":"United States v. Clintwood Elkhorn Mining Co.","cite":"553 U.S. 1","y":2008,"id":"2007/07-308","sc":1,"sum":"Jr., the Court refused to pay Clintwood refunds for the unconstitutionally levied taxes. The Court stated that the remedy for taxes imposed in violation of the Export Clause is the same as for any other unlawful tax: filing a timely administrative refund claim.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"United States v. LMS Holding Co. (In re LMS Holding Co.)","cite":"50 F.3d 1526","y":1995,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/50/1526/","by":{"0":"30"}},{"t":"case","label":"United States v. Mitchell","cite":"403 U.S. 190","y":1971,"id":"1970/798","sc":1,"sum":"A married woman domiciled in Louisiana, where under state law the wife has a present vested interest in community property equal to that of her husband, is personally liable for federal income taxes on her one-half interest in community income realized during the existence of the community, notwithstanding her subsequent renunciation under state law of her community rights, since federal, not state, law governs what …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"United States v. Nordic Vill., Inc.","cite":"503 U.S. 30","y":1992,"id":"1991/90-1629","sc":1,"op":1,"sum":"After respondent Nordic Village, Inc., filed a petition for relief under Chapter 11 of the Bankruptcy Code, one of its officers withdrew funds from the company's corporate account. He sent part of the money to the Internal Revenue Service (IRS), directing it to apply the funds against his individual tax liability, which it did. In a subsequent adversary proceeding, the Bankruptcy Court permitted Nordic Village's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 31-33","1":"31-32, 31","2":"12"}},{"t":"case","label":"United States v. Williams","cite":"514 U.S. 527","y":1995,"id":"1994/94-395","sc":1,"sum":"Section 1346(a)(1) authorizes a refund suit by a party who, though not assessed a tax, paid the tax under protest to remove a federal tax lien from her property.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"United States Postal Serv. v. Flamingo Indus. (USA) Ltd.","cite":"540 U.S. 736","y":2004,"id":"2003/02-1290","sc":1,"sum":"The Court held that the U.S. Postal Service cannot be sued under antitrust laws. The Court acknowledged the Postal Reorganization Act may waive the Postal Service's immunity from suit. However, federal antitrust laws (the Sherman Act, for example) do not allow the federal government - of which the Postal Service is a part - to be sued.","sumSrc":"Oyez","by":{"0":"20","1":"28"}},{"t":"case","label":"Zazzali v. United States (In re DBSI, Inc.)","cite":"869 F.3d 1004","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/869/1004/","op":1,"by":{"0":"4, 8, 9, 17, 40","1":"14, 16, 19, 21, 30, 43, 48"}},{"t":"const","label":"Article I, Section 9, Clause 7","clauses":[["appropriations","Appropriations Clause"]],"text":"No Money shall be drawn from the Treasury, but in Consequence of Appropriations made by Law; and a regular Statement and Account of the Receipts and Expenditures of all public Money shall be published from time to time.","by":{"0":"18, 37","1":"12, 39, 45, 48-49"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"0":"12, 18, 23"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(41)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§101. Definitions","tname":"Bankruptcy","by":{"0":"30, 30","1":"13, 20"}},{"t":"usc","label":"11 U.S.C. § 106","url":"https://www.law.cornell.edu/uscode/text/11/106","subs":["(a)","(a)(1)","(a)(2)","(a)(5)"],"stext":{"head":"§106. Waiver of sovereign immunity","paras":[[0,"(a) Notwithstanding an assertion of sovereign immunity, sovereign immunity is abrogated as to a governmental unit to the extent set forth in this section with respect to the following:"],[1,"(1) Sections 105, 106, 107, 108, 303, 346, 362, 363, 364, 365, 366, 502, 503, 505, 506, 510, 522, 523, 524, 525, 542, 543, 544, 545, 546, 547, 548, 549, 550, 551, 552, 553, 722, 724, 726, 744, 749, 764, 901, 922, 926, 928, 929, 944, 1107, 1141, 1142, 1143, 1146, 1201, 1203, 1205, 1206, 1227, 1231, 1301, 1303, 1305, and 1327 of this title."],[1,"(2) The court may hear and determine any issue arising with respect to the application of such sections to governmental units."],[1,"(3) The court may issue against a governmental unit an order, process, or judgment under such sections or the Federal Rules of Bankruptcy Procedure, including an order or judgment awarding a money recovery, but not including an award of punitive damages. Such order or judgment for costs or fees under this title or the Federal Rules of Bankruptcy Procedure against any governmental unit shall be consistent with the provisions and limitations of section 2412(d)(2)(A) of title 28."],[1,"(4) The enforcement of any such order, process, or judgment against any governmental unit shall be consistent with appropriate nonbankruptcy law applicable to such governmental unit and, in the case of a money judgment against the United States, shall be paid as if it is a judgment rendered by a district court of the United States."],[1,"(5) Nothing in this section shall create any substantive claim for relief or cause of action not otherwise existing under this title, the Federal Rules of Bankruptcy Procedure, or nonbankruptcy law."],[0,"(b) A governmental unit that has filed a proof of claim in the case is deemed to have waived sovereign immunity with respect to a claim against such governmental unit that is property of the estate and that arose out of the same transaction or occurrence out of which the claim of such governmental unit arose."],[0,"(c) Notwithstanding any assertion of sovereign immunity by a governmental unit, there shall be offset against a claim or interest of a governmental unit any claim against such governmental unit that is property of the estate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/106?type=usc&year=mostrecent&link-type=html"},"op":8,"head":"§106. Waiver of sovereign immunity","tname":"Bankruptcy","by":{"0":"29, 29, 29, 29, 30, 30","2":"12, 13, 2, 3, 5-12, 14, 16-21, 3, 6-8, 3, 7, 3, 2, 3, 5-8"}},{"t":"usc","label":"11 U.S.C. § 303","url":"https://www.law.cornell.edu/uscode/text/11/303","subs":["(a)","(i)"],"stext":{"head":"§303. Involuntary cases","paras":[[0,"(a) An involuntary case may be commenced only under chapter 7 or 11 of this title, and only against a person, except a farmer, family farmer, or a corporation that is not a moneyed, business, or commercial corporation, that may be a debtor under the chapter under which such case is commenced."],[0,"(b) An involuntary case against a person is commenced by the filing with the bankruptcy court of a petition under chapter 7 or 11 of this title—"],[1,"(1) by three or more entities, each of which is either a holder of a claim against such person that is not contingent as to liability or the subject of a bona fide dispute as to liability or amount, or an indenture trustee representing such a holder, if such noncontingent, undisputed claims aggregate at least $10,000 1 more than the value of any lien on property of the debtor securing such claims held by the holders of such claims;"],[1,"(2) if there are fewer than 12 such holders, excluding any employee or insider of such person and any transferee of a transfer that is voidable under section 544, 545, 547, 548, 549, or 724(a) of this title, by one or more of such holders that hold in the aggregate at least $10,000 1 of such claims;"],[1,"(3) if such person is a partnership—"],[2,"(A) by fewer than all of the general partners in such partnership; or"],[2,"(B) if relief has been ordered under this title with respect to all of the general partners in such partnership, by a general partner in such partnership, the trustee of such a general partner, or a holder of a claim against such partnership; or"],[1,"(4) by a foreign representative of the estate in a foreign proceeding concerning such person."],[0,"(c) After the filing of a petition under this section but before the case is dismissed or relief is ordered, a creditor holding an unsecured claim that is not contingent, other than a creditor filing under subsection (b) of this section, may join in the petition with the same effect as if such joining creditor were a petitioning creditor under subsection (b) of this section."],[0,"(d) The debtor, or a general partner in a partnership debtor that did not join in the petition, may file an answer to a petition under this section."],[0,"(e) After notice and a hearing, and for cause, the court may require the petitioners under this section to file a bond to indemnify the debtor for such amounts as the court may later allow under subsection (i) of this section."],[0,"(f) Notwithstanding section 363 of this title, except to the extent that the court orders otherwise, and until an order for relief in the case, any business of the debtor may continue to operate, and the debtor may continue to use, acquire, or dispose of property as if an involuntary case concerning the debtor had not been commenced."],[0,"(g) At any time after the commencement of an involuntary case under chapter 7 of this title but before an order for relief in the case, the court, on request of a party in interest, after notice to the debtor and a hearing, and if necessary to preserve the property of the estate or to prevent loss to the estate, may order the United States trustee to appoint an interim trustee under section 701 of this title to take possession of the property of the estate and to operate any business of the debtor. Before an order for relief, the debtor may regain possession of property in the possession of a trustee ordered appointed under this subsection if the debtor files such bond as the court requires, conditioned on the debtor's accounting for and delivering to the trustee, if there is an order for relief in the case, such property, or the value, as of the date the debtor regains possession, of such property."],[0,"(h) If the petition is not timely controverted, the court shall order relief against the debtor in an involuntary case under the chapter under which the petition was filed. Otherwise, after trial, the court shall order relief against the debtor in an involuntary case under the chapter under which the petition was filed, only if—"],[1,"(1) the debtor is generally not paying such debtor's debts as such debts become due unless such debts are the subject of a bona fide dispute as to liability or amount; or"],[1,"(2) within 120 days before the date of the filing of the petition, a custodian, other than a trustee, receiver, or agent appointed or authorized to take charge of less than substantially all of the property of the debtor for the purpose of enforcing a lien against such property, was appointed or took possession."],[0,"(i) If the court dismisses a petition under this section other than on consent of all petitioners and the debtor, and if the debtor does not waive the right to judgment under this subsection, the court may grant judgment—"],[1,"(1) against the petitioners and in favor of the debtor for—"],[2,"(A) costs; or"],[2,"(B) a reasonable attorney's fee; or"],[1,"(2) against any petitioner that filed the petition in bad faith, for—"],[2,"(A) any damages proximately caused by such filing; or"],[2,"(B) punitive damages."],[0,"(j) Only after notice to all creditors and a hearing may the court dismiss a petition filed under this section—"],[1,"(1) on the motion of a petitioner;"],[1,"(2) on consent of all petitioners and the debtor; or"],[1,"(3) for want of prosecution."],[0,"(k)(1) If—"],[1,"(A) the petition under this section is false or contains any materially false, fictitious, or fraudulent statement;"],[1,"(B) the debtor is an individual; and"],[1,"(C) the court dismisses such petition,"],[0,"the court, upon the motion of the debtor, shall seal all the records of the court relating to such petition, and all references to such petition."],[0,"(2) If the debtor is an individual and the court dismisses a petition under this section, the court may enter an order prohibiting all consumer reporting agencies (as defined in section 603(f) of the Fair Credit Reporting Act (15 U.S.C. 1681a(f))) from making any consumer report (as defined in section 603(d) of that Act) that contains any information relating to such petition or to the case commenced by the filing of such petition."],[0,"(3) Upon the expiration of the statute of limitations described in section 3282 of title 18, for a violation of section 152 or 157 of such title, the court, upon the motion of the debtor and for good cause, may expunge any records relating to a petition filed under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/303?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§303. Involuntary cases","tname":"Bankruptcy","by":{"0":"30, 30, 30"}},{"t":"usc","label":"11 U.S.C. § 362","url":"https://www.law.cornell.edu/uscode/text/11/362","stext":{"head":"§362. Automatic stay","paras":[[0,"(a) Except as provided in subsection (b) of this section, a petition filed under section 301, 302, or 303 of this title, or an application filed under section 5(a)(3) of the Securities Investor Protection Act of 1970, operates as a stay, applicable to all entities, of—"],[1,"(1) the commencement or continuation, including the issuance or employment of process, of a judicial, administrative, or other action or proceeding against the debtor that was or could have been commenced before the commencement of the case under this title, or to recover a claim against the debtor that arose before the commencement of the case under this title;"],[1,"(2) the enforcement, against the debtor or against property of the estate, of a judgment obtained before the commencement of the case under this title;"],[1,"(3) any act to obtain possession of property of the estate or of property from the estate or to exercise control over property of the estate;"],[1,"(4) any act to create, perfect, or enforce any lien against property of the estate;"],[1,"(5) any act to create, perfect, or enforce against property of the debtor any lien to the extent that such lien secures a claim that arose before the commencement of the case under this title;"],[1,"(6) any act to collect, assess, or recover a claim against the debtor that arose before the commencement of the case under this title;"],[1,"(7) the setoff of any debt owing to the debtor that arose before the commencement of the case under this title against any claim against the debtor; and"],[1,"(8) the commencement or continuation of a proceeding before the United States Tax Court concerning a tax liability of a debtor that is a corporation for a taxable period the bankruptcy court may determine or concerning the tax liability of a debtor who is an individual for a taxable period ending before the date of the order for relief under this title."],[0,"(b) The filing of a petition under section 301, 302, or 303 of this title, or of an application under section 5(a)(3) of the Securities Investor Protection Act of 1970, does not operate as a stay—"],[1,"(1) under subsection (a) of this section, of the commencement or continuation of a criminal action or proceeding against the debtor;"],[1,"(2) under subsection (a)—"],[2,"(A) of the commencement or continuation of a civil action or proceeding—"],[3,"(i) for the establishment of paternity;"],[3,"(ii) for the establishment or modification of an order for domestic support obligations;"],[3,"(iii) concerning child custody or visitation;"],[3,"(iv) for the dissolution of a marriage, except to the extent that such proceeding seeks to determine the division of property that is property of the estate; or"],[3,"(v) regarding domestic violence;"],[2,"(B) of the collection of a domestic support obligation from property that is not property of the estate;"],[2,"(C) with respect to the withholding of income that is property of the estate or property of the debtor for payment of a domestic support obligation under a judicial or administrative order or a statute;"],[2,"(D) of the withholding, suspension, or restriction of a driver's license, a professional or occupational license, or a recreational license, under State law, as specified in section 466(a)(16) of the Social Security Act;"],[2,"(E) of the reporting of overdue support owed by a parent to any consumer reporting agency as specified in section 466(a)(7) of the Social Security Act;"],[2,"(F) of the interception of a tax refund, as specified in sections 464 and 466(a)(3) of the Social Security Act or under an analogous State law; or"],[2,"(G) of the enforcement of a medical obligation, as specified under title IV of the Social Security Act;"],[1,"(3) under subsection (a) of this section, of any act to perfect, or to maintain or continue the perfection of, an interest in property to the extent that the trustee's rights and powers are subject to such perfection under section 546(b) of this title or to the extent that such act is accomplished within the period provided under section 547(e)(2)(A) of this title;"],[1,"(4) under paragraph (1), (2), (3), or (6) of subsection (a) of this section, of the commencement or continuation of an action or proceeding by a governmental unit or any organization exercising authority under the Convention on the Prohibition of the Development, Production, Stockpiling and Use of Chemical Weapons and on Their Destruction, opened for signature on January 13, 1993, to enforce such governmental unit's or organization's police and regulatory power, including the enforcement of a judgment other than a money judgment, obtained in an action or proceeding by the governmental unit to enforce such governmental unit's or organization's police or regulatory power;"],[1,"[(5) Repealed. Pub. L. 105–277, div. I, title VI, §603(1), Oct. 21, 1998, 112 Stat. 2681–866;]"],[1,"(6) under subsection (a) of this section, of the exercise by a commodity broker, forward contract merchant, stockbroker, financial institution, financial participant, or securities clearing agency of any contractual right (as defined in section 555 or 556) under any security agreement or arrangement or other credit enhancement forming a part of or related to any commodity contract, forward contract or securities contract, or of any contractual right (as defined in section 555 or 556) to offset or net out any termination value, payment amount, or other transfer obligation arising under or in connection with 1 or more such contracts, including any master agreement for such contracts;"],[1,"(7) under subsection (a) of this section, of the exercise by a repo participant or financial participant of any contractual right (as defined in section 559) under any security agreement or arrangement or other credit enhancement forming a part of or related to any repurchase agreement, or of any contractual right (as defined in section 559) to offset or net out any termination value, payment amount, or other transfer obligation arising under or in connection with 1 or more such agreements, including any master agreement for such agreements;"],[1,"(8) under subsection (a) of this section, of the commencement of any action by the Secretary of Housing and Urban Development to foreclose a mortgage or deed of trust in any case in which the mortgage or deed of trust held by the Secretary is insured or was formerly insured under the National Housing Act and covers property, or combinations of property, consisting of five or more living units;"],[1,"(9) under subsection (a), of—"],[2,"(A) an audit by a governmental unit to determine tax liability;"],[2,"(B) the issuance to the debtor by a governmental unit of a notice of tax deficiency;"],[2,"(C) a demand for tax returns; or"],[2,"(D) the making of an assessment for any tax and issuance of a notice and demand for payment of such an assessment (but any tax lien that would otherwise attach to property of the estate by reason of such an assessment shall not take effect unless such tax is a debt of the debtor that will not be discharged in the case and such property or its proceeds are transferred out of the estate to, or otherwise revested in, the debtor)."],[1,"(10) under subsection (a) of this section, of any act by a lessor to the debtor under a lease of nonresidential real property that has terminated by the expiration of the stated term of the lease before the commencement of or during a case under this title to obtain possession of such property;"],[1,"(11) under subsection (a) of this section, of the presentment of a negotiable instrument and the giving of notice of and protesting dishonor of such an instrument;"],[1,"(12) under subsection (a) of this section, after the date which is 90 days after the filing of such petition, of the commencement or continuation, and conclusion to the entry of final judgment, of an action which involves a debtor subject to reorganization pursuant to chapter 11 of this title and which was brought by the Secretary of Transportation under section 31325 of title 46 (including distribution of any proceeds of sale) to foreclose a preferred ship or fleet mortgage, or a security interest in or relating to a vessel or vessel under construction, held by the Secretary of Transportation under chapter 537 of title 46 or section 109(h) of title 49, or under applicable State law;"],[1,"(13) under subsection (a) of this section, after the date which is 90 days after the filing of such petition, of the commencement or continuation, and conclusion to the entry of final judgment, of an action which involves a debtor subject to reorganization pursuant to chapter 11 of this title and which was brought by the Secretary of Commerce under section 31325 of title 46 (including distribution of any proceeds of sale) to foreclose a preferred ship or fleet mortgage in a vessel or a mortgage, deed of trust, or other security interest in a fishing facility held by the Secretary of Commerce under chapter 537 of title 46;"],[1,"(14) under subsection (a) of this section, of any action by an accrediting agency regarding the accreditation status of the debtor as an educational institution;"],[1,"(15) under subsection (a) of this section, of any action by a State licensing body regarding the licensure of the debtor as an educational institution;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/362?type=usc&year=mostrecent&link-type=html"},"head":"§362. Automatic stay","tname":"Bankruptcy","by":{"0":"15","2":"8"}},{"t":"usc","label":"11 U.S.C. § 523","url":"https://www.law.cornell.edu/uscode/text/11/523","subs":["(a)(2)(A)","(a)(1)(B)(ii)","(a)(19)"],"stext":{"head":"§523. Exceptions to discharge","paras":[[0,"(a) A discharge under section 727, 1141, 1192 1 1228(a), 1228(b), or 1328(b) of this title does not discharge an individual debtor from any debt—"],[1,"(1) for a tax or a customs duty—"],[2,"(A) of the kind and for the periods specified in section 507(a)(3) or 507(a)(8) of this title, whether or not a claim for such tax was filed or allowed;"],[2,"(B) with respect to which a return, or equivalent report or notice, if required—"],[3,"(i) was not filed or given; or"],[3,"(ii) was filed or given after the date on which such return, report, or notice was last due, under applicable law or under any extension, and after two years before the date of the filing of the petition; or"],[2,"(C) with respect to which the debtor made a fraudulent return or willfully attempted in any manner to evade or defeat such tax;"],[1,"(2) for money, property, services, or an extension, renewal, or refinancing of credit, to the extent obtained by—"],[2,"(A) false pretenses, a false representation, or actual fraud, other than a statement respecting the debtor's or an insider's financial condition;"],[2,"(B) use of a statement in writing—"],[3,"(i) that is materially false;"],[3,"(ii) respecting the debtor's or an insider's financial condition;"],[3,"(iii) on which the creditor to whom the debtor is liable for such money, property, services, or credit reasonably relied; and"],[3,"(iv) that the debtor caused to be made or published with intent to deceive; or"],[2,"(C)(i) for purposes of subparagraph (A)—"],[3,"(I) consumer debts owed to a single creditor and aggregating more than $500 2 for luxury goods or services incurred by an individual debtor on or within 90 days before the order for relief under this title are presumed to be nondischargeable; and"],[3,"(II) cash advances aggregating more than $750 2 that are extensions of consumer credit under an open end credit plan obtained by an individual debtor on or within 70 days before the order for relief under this title, are presumed to be nondischargeable; and"],[2,"(ii) for purposes of this subparagraph—"],[3,"(I) the terms \"consumer\", \"credit\", and \"open end credit plan\" have the same meanings as in section 103 of the Truth in Lending Act; and"],[3,"(II) the term \"luxury goods or services\" does not include goods or services reasonably necessary for the support or maintenance of the debtor or a dependent of the debtor;"],[1,"(3) neither listed nor scheduled under section 521(a)(1) of this title, with the name, if known to the debtor, of the creditor to whom such debt is owed, in time to permit—"],[2,"(A) if such debt is not of a kind specified in paragraph (2), (4), or (6) of this subsection, timely filing of a proof of claim, unless such creditor had notice or actual knowledge of the case in time for such timely filing; or"],[2,"(B) if such debt is of a kind specified in paragraph (2), (4), or (6) of this subsection, timely filing of a proof of claim and timely request for a determination of dischargeability of such debt under one of such paragraphs, unless such creditor had notice or actual knowledge of the case in time for such timely filing and request;"],[1,"(4) for fraud or defalcation while acting in a fiduciary capacity, embezzlement, or larceny;"],[1,"(5) for a domestic support obligation;"],[1,"(6) for willful and malicious injury by the debtor to another entity or to the property of another entity;"],[1,"(7) to the extent such debt is for a fine, penalty, or forfeiture payable to and for the benefit of a governmental unit, and is not compensation for actual pecuniary loss, other than a tax penalty—"],[2,"(A) relating to a tax of a kind not specified in paragraph (1) of this subsection; or"],[2,"(B) imposed with respect to a transaction or event that occurred before three years before the date of the filing of the petition;"],[1,"(8) unless excepting such debt from discharge under this paragraph would impose an undue hardship on the debtor and the debtor's dependents, for—"],[2,"(A)(i) an educational benefit overpayment or loan made, insured, or guaranteed by a governmental unit, or made under any program funded in whole or in part by a governmental unit or nonprofit institution; or"],[2,"(ii) an obligation to repay funds received as an educational benefit, scholarship, or stipend; or"],[2,"(B) any other educational loan that is a qualified education loan, as defined in section 221(d)(1) of the Internal Revenue Code of 1986, incurred by a debtor who is an individual;"],[1,"(9) for death or personal injury caused by the debtor's operation of a motor vehicle, vessel, or aircraft if such operation was unlawful because the debtor was intoxicated from using alcohol, a drug, or another substance;"],[1,"(10) that was or could have been listed or scheduled by the debtor in a prior case concerning the debtor under this title or under the Bankruptcy Act in which the debtor waived discharge, or was denied a discharge under section 727(a)(2), (3), (4), (5), (6), or (7) of this title, or under section 14c(1), (2), (3), (4), (6), or (7) of such Act;"],[1,"(11) provided in any final judgment, unreviewable order, or consent order or decree entered in any court of the United States or of any State, issued by a Federal depository institutions regulatory agency, or contained in any settlement agreement entered into by the debtor, arising from any act of fraud or defalcation while acting in a fiduciary capacity committed with respect to any depository institution or insured credit union;"],[1,"(12) for malicious or reckless failure to fulfill any commitment by the debtor to a Federal depository institutions regulatory agency to maintain the capital of an insured depository institution, except that this paragraph shall not extend any such commitment which would otherwise be terminated due to any act of such agency;"],[1,"(13) for any payment of an order of restitution issued under title 18, United States Code;"],[1,"(14) incurred to pay a tax to the United States that would be nondischargeable pursuant to paragraph (1);"],[1,"(14A) incurred to pay a tax to a governmental unit, other than the United States, that would be nondischargeable under paragraph (1);"],[1,"(14B) incurred to pay fines or penalties imposed under Federal election law;"],[1,"(15) to a spouse, former spouse, or child of the debtor and not of the kind described in paragraph (5) that is incurred by the debtor in the course of a divorce or separation or in connection with a separation agreement, divorce decree or other order of a court of record, or a determination made in accordance with State or territorial law by a governmental unit;"],[1,"(16) for a fee or assessment that becomes due and payable after the order for relief to a membership association with respect to the debtor's interest in a unit that has condominium ownership, in a share of a cooperative corporation, or a lot in a homeowners association, for as long as the debtor or the trustee has a legal, equitable, or possessory ownership interest in such unit, such corporation, or such lot, but nothing in this paragraph shall except from discharge the debt of a debtor for a membership association fee or assessment for a period arising before entry of the order for relief in a pending or subsequent bankruptcy case;"],[1,"(17) for a fee imposed on a prisoner by any court for the filing of a case, motion, complaint, or appeal, or for other costs and expenses assessed with respect to such filing, regardless of an assertion of poverty by the debtor under subsection (b) or (f)(2) of section 1915 of title 28 (or a similar non-Federal law), or the debtor's status as a prisoner, as defined in section 1915(h) of title 28 (or a similar non-Federal law);"],[1,"(18) owed to a pension, profit-sharing, stock bonus, or other plan established under section 401, 403, 408, 408A, 414, 457, or 501(c) of the Internal Revenue Code of 1986, under—"],[2,"(A) a loan permitted under section 408(b)(1) of the Employee Retirement Income Security Act of 1974, or subject to section 72(p) of the Internal Revenue Code of 1986; or"],[2,"(B) a loan from a thrift savings plan permitted under subchapter III of chapter 84 of title 5, that satisfies the requirements of section 8433(g) of such title;"],[1,"but nothing in this paragraph may be construed to provide that any loan made under a governmental plan under section 414(d), or a contract or account under section 403(b), of the Internal Revenue Code of 1986 constitutes a claim or a debt under this title;"],[1,"(19) that—"],[2,"(A) is for—"],[3,"(i) the violation of any of the Federal securities laws (as that term is defined in section 3(a)(47) of the Securities Exchange Act of 1934), any of the State securities laws, or any regulation or order issued under such Federal or State securities laws; or"],[3,"(ii) common law fraud, deceit, or manipulation in connection with the purchase or sale of any security; and"],[2,"(B) results, before, on, or after the date on which the petition was filed, from—"],[3,"(i) any judgment, order, consent order, or decree entered in any Federal or State judicial or administrative proceeding;"],[3,"(ii) any settlement agreement entered into by the debtor; or"],[3,"(iii) any court or administrative order for any damages, fine, penalty, citation, restitutionary payment, disgorgement payment, attorney fee, cost, or other payment owed by the debtor; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/523?type=usc&year=mostrecent&link-type=html"},"head":"§523. Exceptions to discharge","tname":"Bankruptcy","by":{"0":"26","2":"8, 9"}},{"t":"usc","label":"11 U.S.C. § 541","url":"https://www.law.cornell.edu/uscode/text/11/541","subs":["(c)(2)"],"by":{"0":"4"}},{"t":"usc","label":"11 U.S.C. § 542","url":"https://www.law.cornell.edu/uscode/text/11/542","subs":["(b)"],"by":{"0":"32"}},{"t":"usc","label":"11 U.S.C. § 544","url":"https://www.law.cornell.edu/uscode/text/11/544","subs":["(a)","(b)","(b)(1)","(b)(2)"],"stext":{"head":"§544. Trustee as lien creditor and as successor to certain creditors and purchasers","paras":[[0,"(a) The trustee shall have, as of the commencement of the case, and without regard to any knowledge of the trustee or of any creditor, the rights and powers of, or may avoid any transfer of property of the debtor or any obligation incurred by the debtor that is voidable by—"],[1,"(1) a creditor that extends credit to the debtor at the time of the commencement of the case, and that obtains, at such time and with respect to such credit, a judicial lien on all property on which a creditor on a simple contract could have obtained such a judicial lien, whether or not such a creditor exists;"],[1,"(2) a creditor that extends credit to the debtor at the time of the commencement of the case, and obtains, at such time and with respect to such credit, an execution against the debtor that is returned unsatisfied at such time, whether or not such a creditor exists; or"],[1,"(3) a bona fide purchaser of real property, other than fixtures, from the debtor, against whom applicable law permits such transfer to be perfected, that obtains the status of a bona fide purchaser and has perfected such transfer at the time of the commencement of the case, whether or not such a purchaser exists."],[0,"(b)(1) Except as provided in paragraph (2), the trustee may avoid any transfer of an interest of the debtor in property or any obligation incurred by the debtor that is voidable under applicable law by a creditor holding an unsecured claim that is allowable under section 502 of this title or that is not allowable only under section 502(e) of this title."],[0,"(2) Paragraph (1) shall not apply to a transfer of a charitable contribution (as that term is defined in section 548(d)(3)) that is not covered under section 548(a)(1)(B), by reason of section 548(a)(2). Any claim by any person to recover a transferred contribution described in the preceding sentence under Federal or State law in a Federal or State court shall be preempted by the commencement of the case."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/544?type=usc&year=mostrecent&link-type=html"},"op":21,"ar":2,"head":"§544. Trustee as lien creditor and as successor to certain creditors and purchasers","tname":"Bankruptcy","by":{"0":"2, 2, 22, 22, 22","2":"2, 10, 11, 1-5, 7, 8, 10-14, 16-19, 21-23, 4, 24"}},{"t":"usc","label":"11 U.S.C. § 546","url":"https://www.law.cornell.edu/uscode/text/11/546","subs":["(a)(1)"],"by":{"0":"22"}},{"t":"usc","label":"11 U.S.C. § 547","url":"https://www.law.cornell.edu/uscode/text/11/547","subs":["(b)","(a)(2)","(c)"],"stext":{"head":"§547. Preferences","paras":[[0,"(a) In this section—"],[1,"(1) \"inventory\" means personal property leased or furnished, held for sale or lease, or to be furnished under a contract for service, raw materials, work in process, or materials used or consumed in a business, including farm products such as crops or livestock, held for sale or lease;"],[1,"(2) \"new value\" means money or money's worth in goods, services, or new credit, or release by a transferee of property previously transferred to such transferee in a transaction that is neither void nor voidable by the debtor or the trustee under any applicable law, including proceeds of such property, but does not include an obligation substituted for an existing obligation;"],[1,"(3) \"receivable\" means right to payment, whether or not such right has been earned by performance; and"],[1,"(4) a debt for a tax is incurred on the day when such tax is last payable without penalty, including any extension."],[0,"(b) Except as provided in subsections (c) and (i) of this section, the trustee may, based on reasonable due diligence in the circumstances of the case and taking into account a party's known or reasonably knowable affirmative defenses under subsection (c), avoid any transfer of an interest of the debtor in property—"],[1,"(1) to or for the benefit of a creditor;"],[1,"(2) for or on account of an antecedent debt owed by the debtor before such transfer was made;"],[1,"(3) made while the debtor was insolvent;"],[1,"(4) made—"],[2,"(A) on or within 90 days before the date of the filing of the petition; or"],[2,"(B) between ninety days and one year before the date of the filing of the petition, if such creditor at the time of such transfer was an insider; and"],[1,"(5) that enables such creditor to receive more than such creditor would receive if—"],[2,"(A) the case were a case under chapter 7 of this title;"],[2,"(B) the transfer had not been made; and"],[2,"(C) such creditor received payment of such debt to the extent provided by the provisions of this title."],[0,"(c) The trustee may not avoid under this section a transfer—"],[1,"(1) to the extent that such transfer was—"],[2,"(A) intended by the debtor and the creditor to or for whose benefit such transfer was made to be a contemporaneous exchange for new value given to the debtor; and"],[2,"(B) in fact a substantially contemporaneous exchange;"],[1,"(2) to the extent that such transfer was in payment of a debt incurred by the debtor in the ordinary course of business or financial affairs of the debtor and the transferee, and such transfer was—"],[2,"(A) made in the ordinary course of business or financial affairs of the debtor and the transferee; or"],[2,"(B) made according to ordinary business terms;"],[1,"(3) that creates a security interest in property acquired by the debtor—"],[2,"(A) to the extent such security interest secures new value that was—"],[3,"(i) given at or after the signing of a security agreement that contains a description of such property as collateral;"],[3,"(ii) given by or on behalf of the secured party under such agreement;"],[3,"(iii) given to enable the debtor to acquire such property; and"],[3,"(iv) in fact used by the debtor to acquire such property; and"],[2,"(B) that is perfected on or before 30 days after the debtor receives possession of such property;"],[1,"(4) to or for the benefit of a creditor, to the extent that, after such transfer, such creditor gave new value to or for the benefit of the debtor—"],[2,"(A) not secured by an otherwise unavoidable security interest; and"],[2,"(B) on account of which new value the debtor did not make an otherwise unavoidable transfer to or for the benefit of such creditor;"],[1,"(5) that creates a perfected security interest in inventory or a receivable or the proceeds of either, except to the extent that the aggregate of all such transfers to the transferee caused a reduction, as of the date of the filing of the petition and to the prejudice of other creditors holding unsecured claims, of any amount by which the debt secured by such security interest exceeded the value of all security interests for such debt on the later of—"],[2,"(A)(i) with respect to a transfer to which subsection (b)(4)(A) of this section applies, 90 days before the date of the filing of the petition; or"],[2,"(ii) with respect to a transfer to which subsection (b)(4)(B) of this section applies, one year before the date of the filing of the petition; or"],[2,"(B) the date on which new value was first given under the security agreement creating such security interest;"],[1,"(6) that is the fixing of a statutory lien that is not avoidable under section 545 of this title;"],[1,"(7) to the extent such transfer was a bona fide payment of a debt for a domestic support obligation;"],[1,"(8) if, in a case filed by an individual debtor whose debts are primarily consumer debts, the aggregate value of all property that constitutes or is affected by such transfer is less than $600; or"],[1,"(9) if, in a case filed by a debtor whose debts are not primarily consumer debts, the aggregate value of all property that constitutes or is affected by such transfer is less than $5,000.1"],[0,"(d) The trustee may avoid a transfer of an interest in property of the debtor transferred to or for the benefit of a surety to secure reimbursement of such a surety that furnished a bond or other obligation to dissolve a judicial lien that would have been avoidable by the trustee under subsection (b) of this section. The liability of such surety under such bond or obligation shall be discharged to the extent of the value of such property recovered by the trustee or the amount paid to the trustee."],[0,"(e)(1) For the purposes of this section—"],[1,"(A) a transfer of real property other than fixtures, but including the interest of a seller or purchaser under a contract for the sale of real property, is perfected when a bona fide purchaser of such property from the debtor against whom applicable law permits such transfer to be perfected cannot acquire an interest that is superior to the interest of the transferee; and"],[1,"(B) a transfer of a fixture or property other than real property is perfected when a creditor on a simple contract cannot acquire a judicial lien that is superior to the interest of the transferee."],[0,"(2) For the purposes of this section, except as provided in paragraph (3) of this subsection, a transfer is made—"],[1,"(A) at the time such transfer takes effect between the transferor and the transferee, if such transfer is perfected at, or within 30 days after, such time, except as provided in subsection (c)(3)(B);"],[1,"(B) at the time such transfer is perfected, if such transfer is perfected after such 30 days; or"],[1,"(C) immediately before the date of the filing of the petition, if such transfer is not perfected at the later of—"],[2,"(i) the commencement of the case; or"],[2,"(ii) 30 days after such transfer takes effect between the transferor and the transferee."],[0,"(3) For the purposes of this section, a transfer is not made until the debtor has acquired rights in the property transferred."],[0,"(f) For the purposes of this section, the debtor is presumed to have been insolvent on and during the 90 days immediately preceding the date of the filing of the petition."],[0,"(g) For the purposes of this section, the trustee has the burden of proving the avoidability of a transfer under subsection (b) of this section, and the creditor or party in interest against whom recovery or avoidance is sought has the burden of proving the nonavoidability of a transfer under subsection (c) of this section."],[0,"(h) The trustee may not avoid a transfer if such transfer was made as a part of an alternative repayment schedule between the debtor and any creditor of the debtor created by an approved nonprofit budget and credit counseling agency."],[0,"(i) If the trustee avoids under subsection (b) a transfer made between 90 days and 1 year before the date of the filing of the petition, by the debtor to an entity that is not an insider for the benefit of a creditor that is an insider, such transfer shall be considered to be avoided under this section only with respect to the creditor that is an insider."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/547?type=usc&year=mostrecent&link-type=html"},"head":"§547. Preferences","tname":"Bankruptcy","by":{"0":"2, 32","2":"9, 9, 9, 9"}},{"t":"usc","label":"11 U.S.C. § 548","url":"https://www.law.cornell.edu/uscode/text/11/548","subs":["(a)","(a)(2)"],"stext":{"head":"§548. Fraudulent transfers and obligations","paras":[[0,"(a)(1) The trustee may avoid any transfer (including any transfer to or for the benefit of an insider under an employment contract) of an interest of the debtor in property, or any obligation (including any obligation to or for the benefit of an insider under an employment contract) incurred by the debtor, that was made or incurred on or within 2 years before the date of the filing of the petition, if the debtor voluntarily or involuntarily—"],[1,"(A) made such transfer or incurred such obligation with actual intent to hinder, delay, or defraud any entity to which the debtor was or became, on or after the date that such transfer was made or such obligation was incurred, indebted; or"],[1,"(B)(i) received less than a reasonably equivalent value in exchange for such transfer or obligation; and"],[1,"(ii)(I) was insolvent on the date that such transfer was made or such obligation was incurred, or became insolvent as a result of such transfer or obligation;"],[1,"(II) was engaged in business or a transaction, or was about to engage in business or a transaction, for which any property remaining with the debtor was an unreasonably small capital;"],[1,"(III) intended to incur, or believed that the debtor would incur, debts that would be beyond the debtor's ability to pay as such debts matured; or"],[1,"(IV) made such transfer to or for the benefit of an insider, or incurred such obligation to or for the benefit of an insider, under an employment contract and not in the ordinary course of business."],[0,"(2) A transfer of a charitable contribution to a qualified religious or charitable entity or organization shall not be considered to be a transfer covered under paragraph (1)(B) in any case in which—"],[1,"(A) the amount of that contribution does not exceed 15 percent of the gross annual income of the debtor for the year in which the transfer of the contribution is made; or"],[1,"(B) the contribution made by a debtor exceeded the percentage amount of gross annual income specified in subparagraph (A), if the transfer was consistent with the practices of the debtor in making charitable contributions."],[0,"(b) The trustee of a partnership debtor may avoid any transfer of an interest of the debtor in property, or any obligation incurred by the debtor, that was made or incurred on or within 2 years before the date of the filing of the petition, to a general partner in the debtor, if the debtor was insolvent on the date such transfer was made or such obligation was incurred, or became insolvent as a result of such transfer or obligation."],[0,"(c) Except to the extent that a transfer or obligation voidable under this section is voidable under section 544, 545, or 547 of this title, a transferee or obligee of such a transfer or obligation that takes for value and in good faith has a lien on or may retain any interest transferred or may enforce any obligation incurred, as the case may be, to the extent that such transferee or obligee gave value to the debtor in exchange for such transfer or obligation."],[0,"(d)(1) For the purposes of this section, a transfer is made when such transfer is so perfected that a bona fide purchaser from the debtor against whom applicable law permits such transfer to be perfected cannot acquire an interest in the property transferred that is superior to the interest in such property of the transferee, but if such transfer is not so perfected before the commencement of the case, such transfer is made immediately before the date of the filing of the petition."],[0,"(2) In this section—"],[1,"(A) \"value\" means property, or satisfaction or securing of a present or antecedent debt of the debtor, but does not include an unperformed promise to furnish support to the debtor or to a relative of the debtor;"],[1,"(B) a commodity broker, forward contract merchant, stockbroker, financial institution, financial participant, or securities clearing agency that receives a margin payment, as defined in section 101, 741, or 761 of this title, or settlement payment, as defined in section 101 or 741 of this title, takes for value to the extent of such payment;"],[1,"(C) a repo participant or financial participant that receives a margin payment, as defined in section 741 or 761 of this title, or settlement payment, as defined in section 741 of this title, in connection with a repurchase agreement, takes for value to the extent of such payment;"],[1,"(D) a swap participant or financial participant that receives a transfer in connection with a swap agreement takes for value to the extent of such transfer; and"],[1,"(E) a master netting agreement participant that receives a transfer in connection with a master netting agreement or any individual contract covered thereby takes for value to the extent of such transfer, except that, with respect to a transfer under any individual contract covered thereby, to the extent that such master netting agreement participant otherwise did not take (or is otherwise not deemed to have taken) such transfer for value."],[0,"(3) In this section, the term \"charitable contribution\" means a charitable contribution, as that term is defined in section 170(c) of the Internal Revenue Code of 1986, if that contribution—"],[1,"(A) is made by a natural person; and"],[1,"(B) consists of—"],[2,"(i) a financial instrument (as that term is defined in section 731(c)(2)(C) of the Internal Revenue Code of 1986); or"],[2,"(ii) cash."],[0,"(4) In this section, the term \"qualified religious or charitable entity or organization\" means—"],[1,"(A) an entity described in section 170(c)(1) of the Internal Revenue Code of 1986; or"],[1,"(B) an entity or organization described in section 170(c)(2) of the Internal Revenue Code of 1986."],[0,"(e)(1) In addition to any transfer that the trustee may otherwise avoid, the trustee may avoid any transfer of an interest of the debtor in property that was made on or within 10 years before the date of the filing of the petition, if—"],[1,"(A) such transfer was made to a self-settled trust or similar device;"],[1,"(B) such transfer was by the debtor;"],[1,"(C) the debtor is a beneficiary of such trust or similar device; and"],[1,"(D) the debtor made such transfer with actual intent to hinder, delay, or defraud any entity to which the debtor was or became, on or after the date that such transfer was made, indebted."],[0,"(2) For the purposes of this subsection, a transfer includes a transfer made in anticipation of any money judgment, settlement, civil penalty, equitable order, or criminal fine incurred by, or which the debtor believed would be incurred by—"],[1,"(A) any violation of the securities laws (as defined in section 3(a)(47) of the Securities Exchange Act of 1934 (15 U.S.C. 78c(a)(47))), any State securities laws, or any regulation or order issued under Federal securities laws or State securities laws; or"],[1,"(B) fraud, deceit, or manipulation in a fiduciary capacity or in connection with the purchase or sale of any security registered under section 12 or 15(d) of the Securities Exchange Act of 1934 (15 U.S.C. 78l and 78o(d)) or under section 6 of the Securities Act of 1933 (15 U.S.C. 77f)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/548?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":2,"head":"§548. Fraudulent transfers and obligations","tname":"Bankruptcy","by":{"0":"2, 5, 38, 2, 5, 32","2":"1, 8, 10, 1, 10, 24"}},{"t":"usc","label":"11 U.S.C. § 549","url":"https://www.law.cornell.edu/uscode/text/11/549","subs":["(a)"],"stext":{"head":"§549. Postpetition transactions","paras":[[0,"(a) Except as provided in subsection (b) or (c) of this section, the trustee may avoid a transfer of property of the estate—"],[1,"(1) that occurs after the commencement of the case; and"],[1,"(2)(A) that is authorized only under section 303(f) or 542(c) of this title; or"],[1,"(B) that is not authorized under this title or by the court."],[0,"(b) In an involuntary case, the trustee may not avoid under subsection (a) of this section a transfer made after the commencement of such case but before the order for relief to the extent any value, including services, but not including satisfaction or securing of a debt that arose before the commencement of the case, is given after the commencement of the case in exchange for such transfer, notwithstanding any notice or knowledge of the case that the transferee has."],[0,"(c) The trustee may not avoid under subsection (a) of this section a transfer of an interest in real property to a good faith purchaser without knowledge of the commencement of the case and for present fair equivalent value unless a copy or notice of the petition was filed, where a transfer of an interest in such real property may be recorded to perfect such transfer, before such transfer is so perfected that a bona fide purchaser of such real property, against whom applicable law permits such transfer to be perfected, could not acquire an interest that is superior to such interest of such good faith purchaser. A good faith purchaser without knowledge of the commencement of the case and for less than present fair equivalent value has a lien on the property transferred to the extent of any present value given, unless a copy or notice of the petition was so filed before such transfer was so perfected."],[0,"(d) An action or proceeding under this section may not be commenced after the earlier of—"],[1,"(1) two years after the date of the transfer sought to be avoided; or"],[1,"(2) the time the case is closed or dismissed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/549?type=usc&year=mostrecent&link-type=html"},"head":"§549. Postpetition transactions","tname":"Bankruptcy","by":{"0":"2, 32","2":"8, 13"}},{"t":"usc","label":"11 U.S.C. § 550","url":"https://www.law.cornell.edu/uscode/text/11/550","subs":["(a)","(b)","(d)"],"stext":{"head":"§550. Liability of transferee of avoided transfer","paras":[[0,"(a) Except as otherwise provided in this section, to the extent that a transfer is avoided under section 544, 545, 547, 548, 549, 553(b), or 724(a) of this title, the trustee may recover, for the benefit of the estate, the property transferred, or, if the court so orders, the value of such property, from—"],[1,"(1) the initial transferee of such transfer or the entity for whose benefit such transfer was made; or"],[1,"(2) any immediate or mediate transferee of such initial transferee."],[0,"(b) The trustee may not recover under section 1 (a)(2) of this section from—"],[1,"(1) a transferee that takes for value, including satisfaction or securing of a present or antecedent debt, in good faith, and without knowledge of the voidability of the transfer avoided; or"],[1,"(2) any immediate or mediate good faith transferee of such transferee."],[0,"(c) If a transfer made between 90 days and one year before the filing of the petition—"],[1,"(1) is avoided under section 547(b) of this title; and"],[1,"(2) was made for the benefit of a creditor that at the time of such transfer was an insider;"],[0,"the trustee may not recover under subsection (a) from a transferee that is not an insider."],[0,"(d) The trustee is entitled to only a single satisfaction under subsection (a) of this section."],[0,"(e)(1) A good faith transferee from whom the trustee may recover under subsection (a) of this section has a lien on the property recovered to secure the lesser of—"],[1,"(A) the cost, to such transferee, of any improvement made after the transfer, less the amount of any profit realized by or accruing to such transferee from such property; and"],[1,"(B) any increase in the value of such property as a result of such improvement, of the property transferred."],[0,"(2) In this subsection, \"improvement\" includes—"],[1,"(A) physical additions or changes to the property transferred;"],[1,"(B) repairs to such property;"],[1,"(C) payment of any tax on such property;"],[1,"(D) payment of any debt secured by a lien on such property that is superior or equal to the rights of the trustee; and"],[1,"(E) preservation of such property."],[0,"(f) An action or proceeding under this section may not be commenced after the earlier of—"],[1,"(1) one year after the avoidance of the transfer on account of which recovery under this section is sought; or"],[1,"(2) the time the case is closed or dismissed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/550?type=usc&year=mostrecent&link-type=html"},"head":"§550. Liability of transferee of avoided transfer","tname":"Bankruptcy","by":{"0":"12, 39","2":"20, 23, 24, 23, 24, 16"}},{"t":"usc","label":"26 U.S.C. § 6323","url":"https://www.law.cornell.edu/uscode/text/26/6323","stext":{"head":"§6323. Validity and priority against certain persons","paras":[[0,"(a) Purchasers, holders of security interests, mechanic's lienors, and judgment lien creditors"],[0,"The lien imposed by section 6321 shall not be valid as against any purchaser, holder of a security interest, mechanic's lienor, or judgment lien creditor until notice thereof which meets the requirements of subsection (f) has been filed by the Secretary."],[0,"(b) Protection for certain interests even though notice filed"],[0,"Even though notice of a lien imposed by section 6321 has been filed, such lien shall not be valid—"],[0,"(1) Securities"],[1,"With respect to a security (as defined in subsection (h)(4))—"],[2,"(A) as against a purchaser of such security who at the time of purchase did not have actual notice or knowledge of the existence of such lien; and"],[2,"(B) as against a holder of a security interest in such security who, at the time such interest came into existence, did not have actual notice or knowledge of the existence of such lien."],[0,"(2) Motor vehicles"],[1,"With respect to a motor vehicle (as defined in subsection (h)(3)), as against a purchaser of such motor vehicle, if—"],[2,"(A) at the time of the purchase such purchaser did not have actual notice or knowledge of the existence of such lien, and"],[2,"(B) before the purchaser obtains such notice or knowledge, he has acquired possession of such motor vehicle and has not thereafter relinquished possession of such motor vehicle to the seller or his agent."],[0,"(3) Personal property purchased at retail"],[1,"With respect to tangible personal property purchased at retail, as against a purchaser in the ordinary course of the seller's trade or business, unless at the time of such purchase such purchaser intends such purchase to (or knows such purchase will) hinder, evade, or defeat the collection of any tax under this title."],[0,"(4) Personal property purchased in casual sale"],[1,"With respect to household goods, personal effects, or other tangible personal property described in section 6334(a) purchased (not for resale) in a casual sale for less than $1,000, as against the purchaser, but only if such purchaser does not have actual notice or knowledge (A) of the existence of such lien, or (B) that this sale is one of a series of sales."],[0,"(5) Personal property subject to possessory lien"],[1,"With respect to tangible personal property subject to a lien under local law securing the reasonable price of the repair or improvement of such property, as against a holder of such a lien, if such holder is, and has been, continuously in possession of such property from the time such lien arose."],[0,"(6) Real property tax and special assessment liens"],[1,"With respect to real property, as against a holder of a lien upon such property, if such lien is entitled under local law to priority over security interests in such property which are prior in time, and such lien secures payment of—"],[2,"(A) a tax of general application levied by any taxing authority based upon the value of such property;"],[2,"(B) a special assessment imposed directly upon such property by any taxing authority, if such assessment is imposed for the purpose of defraying the cost of any public improvement; or"],[2,"(C) charges for utilities or public services furnished to such property by the United States, a State or political subdivision thereof, or an instrumentality of any one or more of the foregoing."],[0,"(7) Residential property subject to a mechanic's lien for certain repairs and improvements"],[1,"With respect to real property subject to a lien for repair or improvement of a personal residence (containing not more than four dwelling units) occupied by the owner of such residence, as against a mechanic's lienor, but only if the contract price on the contract with the owner is not more than $5,000."],[0,"(8) Attorneys' liens"],[1,"With respect to a judgment or other amount in settlement of a claim or of a cause of action, as against an attorney who, under local law, holds a lien upon or a contract enforcible against such judgment or amount, to the extent of his reasonable compensation for obtaining such judgment or procuring such settlement, except that this paragraph shall not apply to any judgment or amount in settlement of a claim or of a cause of action against the United States to the extent that the United States offsets such judgment or amount against any liability of the taxpayer to the United States."],[0,"(9) Certain insurance contracts"],[1,"With respect to a life insurance, endowment, or annuity contract, as against the organization which is the insurer under such contract, at any time—"],[2,"(A) before such organization had actual notice or knowledge of the existence of such lien;"],[2,"(B) after such organization had such notice or knowledge, with respect to advances required to be made automatically to maintain such contract in force under an agreement entered into before such organization had such notice or knowledge; or"],[2,"(C) after satisfaction of a levy pursuant to section 6332(b), unless and until the Secretary delivers to such organization a notice, executed after the date of such satisfaction, of the existence of such lien."],[0,"(10) Deposit-secured loans"],[1,"With respect to a savings deposit, share, or other account with an institution described in section 581 or 591, to the extent of any loan made by such institution without actual notice or knowledge of the existence of such lien, as against such institution, if such loan is secured by such account."],[0,"(c) Protection for certain commercial transactions financing agreements, etc."],[0,"(1) In general"],[1,"To the extent provided in this subsection, even though notice of a lien imposed by section 6321 has been filed, such lien shall not be valid with respect to a security interest which came into existence after tax lien filing but which—"],[2,"(A) is in qualified property covered by the terms of a written agreement entered into before tax lien filing and constituting—"],[3,"(i) a commercial transactions financing agreement,"],[3,"(ii) a real property construction or improvement financing agreement, or"],[3,"(iii) an obligatory disbursement agreement, and"],[2,"(B) is protected under local law against a judgment lien arising, as of the time of tax lien filing, out of an unsecured obligation."],[0,"(2) Commercial transactions financing agreement"],[1,"For purposes of this subsection—"],[0,"(A) Definition"],[2,"The term \"commercial transactions financing agreement\" means an agreement (entered into by a person in the course of his trade or business)—"],[3,"(i) to make loans to the taxpayer to be secured by commercial financing security acquired by the taxpayer in the ordinary course of his trade or business, or"],[3,"(ii) to purchase commercial financing security (other than inventory) acquired by the taxpayer in the ordinary course of his trade or business;"],[2,"but such an agreement shall be treated as coming within the term only to the extent that such loan or purchase is made before the 46th day after the date of tax lien filing or (if earlier) before the lender or purchaser had actual notice or knowledge of such tax lien filing."],[0,"(B) Limitation on qualified property"],[2,"The term \"qualified property\", when used with respect to a commercial transactions financing agreement, includes only commercial financing security acquired by the taxpayer before the 46th day after the date of tax lien filing."],[0,"(C) Commercial financing security defined"],[2,"The term \"commercial financing security\" means (i) paper of a kind ordinarily arising in commercial transactions, (ii) accounts receivable, (iii) mortgages on real property, and (iv) inventory."],[0,"(D) Purchaser treated as acquiring security interest"],[2,"A person who satisfies subparagraph (A) by reason of clause (ii) thereof shall be treated as having acquired a security interest in commercial financing security"],[0,"(3) Real property construction or improvement financing agreement"],[1,"For purposes of this subsection—"],[0,"(A) Definition"],[2,"The term \"real property construction or improvement financing agreement\" means an agreement to make cash disbursements to finance—"],[3,"(i) the construction or improvement of real property,"],[3,"(ii) a contract to construct or improve real property, or"],[3,"(iii) the raising or harvesting of a farm crop or the raising of livestock or other animals."],[2,"For purposes of clause (iii), the furnishing of goods and services shall be treated as the disbursement of cash."],[0,"(B) Limitation on qualified property"],[2,"The term \"qualified property\", when used with respect to a real property construction or improvement financing agreement, includes only—"],[3,"(i) in the case of subparagraph (A)(i), the real property with respect to which the construction or improvement has been or is to be made,"],[3,"(ii) in the case of subparagraph (A)(ii), the proceeds of the contract described therein, and"],[3,"(iii) in the case of subparagraph (A)(iii), property subject to the lien imposed by section 6321 at the time of tax lien filing and the crop or the livestock or other animals referred to in subparagraph (A)(iii)."],[0,"(4) Obligatory disbursement agreement"],[1,"For purposes of this subsection—"],[0,"(A) Definition"],[2,"The term \"obligatory disbursement agreement\" means an agreement (entered into by a person in the course of his trade or business) to make disbursements, but such an agreement shall be treated as coming within the term only to the extent of disbursements which are required to be made by reason of the intervention of the rights of a person other than the taxpayer."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6323?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§6323. Validity and priority against certain persons","tname":"Internal Revenue Code","by":{"0":"30"}},{"t":"usc","label":"26 U.S.C. § 6511","url":"https://www.law.cornell.edu/uscode/text/26/6511","subs":["(a)"],"by":{"0":"38"}},{"t":"usc","label":"26 U.S.C. § 6532","url":"https://www.law.cornell.edu/uscode/text/26/6532","by":{"0":"38"}},{"t":"usc","label":"26 U.S.C. § 7421","url":"https://www.law.cornell.edu/uscode/text/26/7421","subs":["(a)","(b)"],"by":{"0":"35, 35"}},{"t":"usc","label":"26 U.S.C. § 7422","url":"https://www.law.cornell.edu/uscode/text/26/7422","subs":["(a)"],"by":{"0":"35"}},{"t":"usc","label":"26 U.S.C. § 7426","url":"https://www.law.cornell.edu/uscode/text/26/7426","subs":["(a)(3)","(a)(4)"],"by":{"0":"39, 36, 36"}},{"t":"usc","label":"28 U.S.C. § 1409","url":"https://www.law.cornell.edu/uscode/text/28/1409","stext":{"head":"§1409. Venue of proceedings arising under title 11 or arising in or related to cases under title 11","paras":[[0,"(a) Except as otherwise provided in subsections (b) and (d), a proceeding arising under title 11 or arising in or related to a case under title 11 may be commenced in the district court in which such case is pending."],[0,"(b) Except as provided in subsection (d) of this section, a trustee in a case under title 11 may commence a proceeding arising in or related to such case to recover a money judgment of or property worth less than $1,000 1 or a consumer debt of less than $15,000,1 or a debt (excluding a consumer debt) against a noninsider of less than $25,000, only in the district court for the district in which the defendant resides."],[0,"(c) Except as provided in subsection (b) of this section, a trustee in a case under title 11 may commence a proceeding arising in or related to such case as statutory successor to the debtor or creditors under section 541 or 544(b) of title 11 in the district court for the district where the State or Federal court sits in which, under applicable nonbankruptcy venue provisions, the debtor or creditors, as the case may be, may have commenced an action on which such proceeding is based if the case under title 11 had not been commenced."],[0,"(d) A trustee may commence a proceeding arising under title 11 or arising in or related to a case under title 11 based on a claim arising after the commencement of such case from the operation of the business of the debtor only in the district court for the district where a State or Federal court sits in which, under applicable nonbankruptcy venue provisions, an action on such claim may have been brought."],[0,"(e) A proceeding arising under title 11 or arising in or related to a case under title 11, based on a claim arising after the commencement of such case from the operation of the business of the debtor, may be commenced against the representative of the estate in such case in the district court for the district where the State or Federal court sits in which the party commencing such proceeding may, under applicable nonbankruptcy venue provisions, have brought an action on such claim, or in the district court in which such case is pending."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1409?type=usc&year=mostrecent&link-type=html"},"head":"§1409. Venue of proceedings arising under title 11 or arising in or related to cases under title 11","tname":"Judiciary and Judicial Procedure","by":{"0":"17","1":"29"}},{"t":"case","label":"Acme Harvester Co. v. Beekman Lumber Co.","cite":"222 U.S. 300","y":1911,"id":"scdb/1911-024","sc":1,"sum":"The denial of a right claimed under the judgment of a Federal court lays the foundation for a review in this court, and where the state court proceeds to judgment on the ground that bankruptcy proceedings against the defendant had been concluded by denial of adjudication and the injunction against suits in the state court thereby dissolved this court has jurisdiction.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"39"}},{"t":"case","label":"Allen v. Cooper","cite":"589 U.S. 248","y":2020,"id":"2019/18-877","sc":1,"sum":"The Court held that the Copyright Remedy Clarification Act was not a valid abrogation of state sovereign immunity to allow authors of original expression to sue states who infringe their federal copyrights.","sumSrc":"Oyez","by":{"1":"32-33","2":"14"}},{"t":"case","label":"Armed Forces Bank NA v. Dragoo","cite":"2018 WL 8621584","y":2018,"court":"D. Ariz. Sept. 28","by":{"1":"36"}},{"t":"case","label":"Bartenwerfer v. Buckley","cite":"598 U.S. 69","y":2023,"id":"2022/21-908","sc":1,"sum":"Pursuant to §523(a)(2)(A) of the Bankruptcy Code, a debtor like Kate Bartenwerfer who is liable for her partner’s fraud cannot discharge that debt in bankruptcy, regardless of her own culpability.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"34"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of Fed. Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Burwell v. Hobby Lobby Stores, Inc.","cite":"573 U.S. 682","y":2014,"id":"2013/13-354","sc":1,"sum":"The Court decided that the Affordable Care Act's requirement of for-profit corporations to supply its employees with contraceptives that go against the owners' beliefs is unconstitutional under the Religious Freedom Restoration Act of 1993.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Cent. Va. Cmty. Coll. v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"sum":"The Court ruled that states cannot invoke sovereign immunity as a defense in bankruptcy proceedings. Rather than ruling on the power of Congress under the Bankruptcy Clause to waive states' immunity, as the bankruptcy court did, the Court held that ratification of the Clause itself involved a subordination of state sovereign immunity.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"CFTC v. Weintraub","cite":"471 U.S. 343","y":1985,"id":"1984/84-261","sc":1,"sum":"The Supreme Court held that a bankruptcy trustee does have the power to waive attorney client privilege for communications that occurred before filing the bankruptcy petition. This power is held by the management of a corporation, and a bankruptcy trustee is merely a new form of management.","sumSrc":"Oyez","by":{"1":"3"}},{"t":"case","label":"Cleveland v. United States","cite":"531 U.S. 12","y":2000,"id":"2000/99-804","sc":1,"sum":"The Court held that State and municipal licenses in general, and Louisiana's video poker licenses in particular, do not rank as \"property,\" for purposes of federal law, in the hands of the official licensor.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Cook v. United States (In re Yahweh Ctr., Inc.)","cite":"27 F.4th 960","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/27/960/","op":1,"by":{"1":"19, 40"}},{"t":"case","label":"Dole Food Co. v. Patrickson","cite":"538 U.S. 468","y":2003,"id":"2002/01-593","sc":1,"sum":"The Court held, 7-2, that a foreign state must itself own a majority of the shares of a corporation if the corporation is to be deemed an instrumentality of the state under the provisions of the FSIA and, 9-0, that instrumentality status is determined at the time of the filing of the complaint.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Exxon Shipping Co. v. Baker","cite":"554 U.S. 471","y":2008,"id":"2007/07-219","sc":1,"sum":"On the second issue, a 5-4 majority held that judges are free to create remedies in maritime cases where Congress has not legislated in the area. However, this freedom can be lost if Congress passes legislation restraining such judicial activism. Justice David Souter delivered the opinion of the Court.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Georgelas v. Desert Hill Ventures, Inc.","cite":"45 F.4th 1193","y":2022,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/45/1193/","by":{"1":"36"}},{"t":"case","label":"Gobeille v. Liberty Mut. Ins. Co.","cite":"577 U.S. 312","y":2016,"id":"2015/14-181","sc":1,"sum":"The Court determined that the reporting requirements of the Employee Retirement Income Security Act of 1974 (ERISA) preempt a Vermont state statute regarding reporting requirements as applied to a self-insured employee health plan.","sumSrc":"Oyez","by":{"1":"45-46"}},{"t":"case","label":"Hafen v. Taylor","cite":"2021 WL 3194367","y":2021,"court":"D. Utah July 28","by":{"1":"36"}},{"t":"case","label":"Hemphill v. New York","cite":"595 U.S. 140","y":2022,"id":"2021/20-637","sc":1,"sum":"The trial court’s admission—over Hemphill’s objection—of the plea allocution transcript of an unavailable witness violated Hemphill’s Sixth Amendment right to confront the witnesses against him.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"37"}},{"t":"case","label":"Hughes v. Talen Energy Mktg., LLC","cite":"578 U.S. 150","y":2016,"id":"2015/14-614","sc":1,"sum":"The Court determined that the Federal Power Act preempted state regulation of utility contracts and sales.","sumSrc":"Oyez","by":{"1":"46-47"}},{"t":"case","label":"Husky Int’l Elecs., Inc. v. Ritz","cite":"578 U.S. 355","y":2016,"id":"2015/15-145","sc":1,"sum":"The Court determined that the “actual fraud” language of the bankruptcy statute encompasses traditional forms of fraud and is not limited to fraudulent representation.","sumSrc":"Oyez","by":{"1":"4"}},{"t":"case","label":"Kansas v. Garcia","cite":"589 U.S. 191","y":2020,"id":"2019/17-834","sc":1,"sum":"A case in which the Court upheld Kansas's prosecution of noncitizens who used stolen social security numbers to gain employment.","sumSrc":"Oyez","by":{"1":"45, 47"}},{"t":"case","label":"Kimel v. Fla. Bd. of Regents","cite":"528 U.S. 62","y":2000,"id":"1999/98-791","sc":1,"sum":"The Court held that the ADEA contains a clear statement of Congress' intent to abrogate the states' immunity, but that the abrogation exceeds Congress' authority under the Fourteenth Amendment. \"States may discriminate on the basis of age without offending the Fourteenth Amendment if the age classification in question is rationally related to a legitimate state interest,\" wrote Justice O'Connor for the Court.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Law v. Siegel","cite":"571 U.S. 415","y":2014,"id":"2013/12-5196","sc":1,"sum":"The Court found that a bankruptcy court may not enforce specific statutory exceptions.","sumSrc":"Oyez","by":{"1":"3, 42"}},{"t":"case","label":"Lebron v. Nat’l R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"sum":"Where, as here, the Government creates a corporation by special law, for the furtherance of governmental objectives, and retains for itself permanent authority to appoint a majority of that corporation's directors, the corporation is part of the Government for purposes of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37-38"}},{"t":"case","label":"Mission Prod. Holdings, Inc. v. Tempnology, LLC","cite":"587 U.S. 370","y":2019,"id":"2018/17-1657","sc":1,"sum":"A bankruptcy debtor’s rejection of an executory contract under 11 U. S. C. §365 has the same effect as a breach of that contract outside bankruptcy; such an act thus cannot rescind rights that the contract previously granted.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"3-4, 40"}},{"t":"case","label":"Ohio Adjutant Gen.’s Dep’t v. FLRA","cite":"598 U.S. 449","y":2023,"id":"2022/21-1454","sc":1,"sum":"The Federal Labor Relations Authority had jurisdiction over this labor dispute because a State National Guard acts as a federal agency for purposes of the Federal Service Labor-Management Relations Statute, 5 U. S. C. §7101 et seq., when it hires and supervises dual-status technicians serving in their civilian role.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"38, 38","2":"20"}},{"t":"case","label":"Oliphant v. Moore","cite":"293 S.W. 541","y":1927,"court":"Tenn.","url":"https://www.courtlistener.com/c/S.W./293/541/","by":{"1":"35"}},{"t":"case","label":"Oneok, Inc. v. Learjet, Inc.","cite":"575 U.S. 373","y":2015,"id":"2014/13-271","sc":1,"sum":"The Court held that the Natural Gas Act does not pre-empt state law claims brought by litigants who purchased gas in retail transactions.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Patel v. Garland","cite":"596 U.S. 328","y":2022,"id":"2021/20-979","sc":1,"sum":"Federal courts lack jurisdiction to review facts found as part of any judgment relating to the granting of discretionary-relief in immigration proceedings enumerated under 8 U. S. C. §1252(a)(2)(B)(i).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17"}},{"t":"case","label":"Polselli v. IRS","cite":"598 U.S. 432","y":2023,"id":"2022/21-1599","sc":1,"sum":"When the Internal Revenue Service issues a summons pursuant to 26 U. S. C. §7602(a) in aid of collecting a tax liability, the exception to the notice requirement in §7609(c)(2)(D)(i) applies even if the delinquent taxpayer has no legal interest in the accounts or records summoned.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"44"}},{"t":"case","label":"Pugin v. Garland","cite":"599 U.S. 600","y":2023,"id":"2022/22-23","sc":1,"sum":"An offense may “relate to” obstruction of justice under the Immigration and Nationality Act’s definition of an “aggravated felony,” 8 U. S. C. §1101(a)(43)(S), even if the offense does not require that an investigation or proceeding be pending.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"15"}},{"t":"case","label":"Sargeant v. Al Saleh","cite":"512 S.W.3d 399","y":2016,"court":"Tex. Ct. App.","url":"https://www.courtlistener.com/c/S.W.3d/512/399/","by":{"1":"35"}},{"t":"case","label":"Siegel v. Fitzgerald","cite":"596 U.S. 464","y":2022,"id":"2021/21-441","sc":1,"sum":"Congress’ enactment of a significant fee increase that exempted debtors in two States violated the uniformity requirement of the Bankruptcy Clause.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"25"}},{"t":"case","label":"Stellwagen v. Clum","cite":"245 U.S. 605","y":1918,"id":"scdb/1917-183","sc":1,"sum":"The Bankruptcy. Act as it was on the dates herein mentioned (February 2,1910, November 9,1910) did not operate to suspend § 6343 of the Revised Statutes of Ohio as it stood February 2, 1910, or the sections into which that section was divided and numbered by the General Code of Ohio, approved February 15, 1910, viz: §§ 11102-11105, as such sections existed May 5,1910.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"25-26"}},{"t":"case","label":"Sugartown Worldwide LLC v. Shanks","cite":"2015 WL 1312572","y":2015,"court":"E.D. Pa. Mar. 24","by":{"1":"36"}},{"t":"case","label":"Tabor v. Davis (In re Davis)","cite":"2016 WL 11696269","y":2016,"court":"Bankr. W.D. Tenn. June 15","by":{"1":"36-37"}},{"t":"case","label":"Tenn. Student Assistance Corp. v. Hood","cite":"541 U.S. 440","y":2004,"id":"2003/02-1606","sc":1,"sum":"Instead, the Court ruled that discharging a debt owed to a state in a bankruptcy procedure is different from a suit and therefore not barred by sovereign immunity. \"A bankruptcy court is able to provide the debtor a fresh start in this manner ... because the court's jurisdiction is premised on the debtor and his estate, and not on the creditors,\" wrote the Court.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"United States v. Brosnan","cite":"363 U.S. 237","y":1960,"id":"1959/137","sc":1,"sum":"Under Pennsylvania law, the sheriff's sale under a writ of fierifacias was a judicial sale; but the doctrine of sovereign immunity from unconsented suits has not yet been","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"United States v. Mitchell","cite":"463 U.S. 206","y":1983,"id":"1982/81-1748","sc":1,"op":1,"sum":"The United States is accountable in money damages for alleged breaches of trust in connection with its management of forest resources on allotted lands of the Quinault Reservation.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"United States v. Taylor","cite":"596 U.S. 845","y":2022,"id":"2021/20-1459","sc":1,"sum":"Attempted Hobbs Act robbery does not qualify as a “crime of violence” under 18 U. S. C. §924(c)(3)(A) because no element of the offense requires proof that the defendant used, attempted to use, or threatened to use force.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"38-39"}},{"t":"case","label":"United States v. Tohono O’odham Nation","cite":"563 U.S. 307","y":2011,"id":"2010/09-846","sc":1,"sum":"The Court held that the Court of Federal Claims lacked jurisdiction to hear a suit against the federal government about a claim already being litigated against the government in another court, even when the lawsuits seek different relief based on the same set of facts.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"United States v. Whiting Pools, Inc.","cite":"462 U.S. 198","y":1983,"id":"1982/82-215","sc":1,"sum":"Section 542(a) of the Bankruptcy Reform Act of 1978 (Act) requires an entity, other than a custodian, in possession of property of the debtor that the trustee in bankruptcy can use, sell, or lease under § 363 to deliver that property to the trustee. Section 543(b)(1) requires a custodian in possession or control of any pioperty of the debtor to deliver the property to the trustee. Promptly after the Internal Revenue …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Watson v. United States","cite":"552 U.S. 74","y":2007,"id":"2007/06-571","sc":1,"by":{"1":"34"}},{"t":"case","label":"Wells Fargo Bank v. Akanan","cite":"2021 WL 12203532","y":2021,"court":"W.D. Pa. June 15","by":{"1":"35"}},{"t":"case","label":"Woods & Erickson, LLP v. Leonard (In re AVI, Inc.)","cite":"389 B.R. 721","y":2008,"court":"B.A.P. 9th Cir.","url":"https://www.courtlistener.com/c/B.R./389/721/","by":{"1":"34"}},{"t":"const","label":"Amendment XI","clauses":[["eleventh-amendment","Eleventh Amendment"]],"text":"The Judicial power of the United States shall not be construed to extend to any suit in law or equity, commenced or prosecuted against one of the United States by Citizens of another State, or by Citizens or Subjects of any Foreign State.","by":{"1":"33"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","by":{"1":"15"}},{"t":"usc","label":"11 U.S.C. § 503","url":"https://www.law.cornell.edu/uscode/text/11/503","by":{"1":"6, 41"}},{"t":"usc","label":"11 U.S.C. § 764","url":"https://www.law.cornell.edu/uscode/text/11/764","by":{"1":"4, 14"}},{"t":"usc","label":"15 U.S.C. § 1122","url":"https://www.law.cornell.edu/uscode/text/15/1122","by":{"1":"16"}},{"t":"usc","label":"20 U.S.C. § 1403","url":"https://www.law.cornell.edu/uscode/text/20/1403","by":{"1":"16"}},{"t":"usc","label":"26 U.S.C. § 6321","url":"https://www.law.cornell.edu/uscode/text/26/6321","by":{"1":"44"}},{"t":"usc","label":"31 U.S.C. § 3104","url":"https://www.law.cornell.edu/uscode/text/31/3104","by":{"1":"49"}},{"t":"case","label":"Resp. Br., Ohio Adjutant Gen.’s Dep’t v. FLRA","cite":"21 F.4th 401","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/21/401/","by":{"1":"38"}},{"t":"case","label":"U.S. Br., Glover v. United States","cite":"531 U.S. 198","y":2001,"id":"2000/99-8576","sc":1,"sum":"The Court held that Court of appeals erred in engrafting onto the prejudice branch of the Strickland test the requirement that any increase in sentence must meet a standard of significance. Thus, the denial of Glover's motion to correct his sentence was reversed and remanded.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"U.S. Br., Lamar, Archer & Cofrin, LLP v. Appling","cite":"584 U.S. 709","y":2018,"url":"https://supreme.justia.com/cases/federal/us/584/709/","sc":1,"op":1,"by":{"1":"15"}},{"t":"case","label":"Buckman Co. v. Plaintiffs’ Legal Comm.","cite":"531 U.S. 341","y":2001,"id":"2000/98-1768","sc":1,"sum":"The Court held that the plaintiffs' state-law fraud-on-the-FDA claims conflicted with, and were therefore pre-empted by, the FDCA, as amended by the MDA. \"The conflict,\" wrote Chief Justice Rehnquist for the Court, \"stems from the fact that the federal statutory scheme amply empowers the FDA to punish and deter fraud against the Agency, and that this authority is used by the Agency to achieve a somewhat delicate balance of statutory objectives.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Cameron v. EMW Women’s Surgical Ctr., P.S.C.","cite":"595 U.S. 267","y":2022,"id":"2021/20-601","sc":1,"op":1,"sum":"The Court of Appeals erred in denying the Kentucky attorney general’s motion to intervene on the Commonwealth’s behalf in litigation concerning Kentucky House Bill 454.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"19"}},{"t":"case","label":"Dewsnup v. Timm","cite":"502 U.S. 410","y":1992,"id":"1991/90-741","sc":1,"sum":"Section 506(d) does not allow Dewsnup to \"strip down\" respondents' lien to the judicially determined value of the collateral, because respondents' claim is secured by a lien and has been fully allowed pursuant to § 502 and, therefore, cannot be classified as \"not an allowed secured claim\" for purposes of the lien-voiding provision of § 506(d).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"op":1,"ar":10,"sum":"Explaining that the phrase “ `[i]n relation to' ” is “context sensitive”.","sumSrc":"opinion","by":{"2":"6"}},{"t":"case","label":"Financial Oversight & Management Board for Puerto Rico v. Centro de Periodismo Investigativo","cite":"598 U.S. 339","y":2023,"id":"2022/22-96","sc":1,"op":1,"sum":"Nothing in the Puerto Rico Oversight, Management, and Economic Stability Act—including its jurisdictional provision, 48 U. S. C. §2126(a)—categorically abrogates any sovereign immunity the Financial Oversight and Management Board for Puerto Rico enjoys from legal claims.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"20, 21"}},{"t":"case","label":"Genova v. Gottlieb (In re Orange Cnty. Sanitation, Inc.)","cite":"221 B.R. 323","y":1997,"court":"Bankr. S.D.N.Y.","url":"https://www.courtlistener.com/c/B.R./221/323/","by":{"2":"24"}},{"t":"case","label":"(I) Cases—Continued: Lee v. Schweiker","cite":"739 F.2d 870","y":1984,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/739/870/","by":{"2":"13"}},{"t":"case","label":"M. Fabrikant & Sons, Inc. v. JP Morgan Chase Bank (In re M. Fabrikant & Sons, Inc.)","cite":"394 B.R. 721","y":2008,"court":"Bankr. S.D.N.Y.","url":"https://www.courtlistener.com/c/B.R./394/721/","by":{"2":"24"}},{"t":"case","label":"Securities Investor Prot. Corp. v. Bernard L. Madoff Inv. Securities LLC","cite":"501 B.R. 26","y":2013,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/B.R./501/26/","by":{"2":"24"}},{"t":"law","label":"Pub. L. No. 109-8","url":"https://www.govinfo.gov/link/plaw/109/public/8","by":{"2":"10"}},{"t":"usc","label":"15 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/15/1681","by":{"2":"12"}},{"t":"usc","label":"5 U.S.C. § 7103","url":"https://www.law.cornell.edu/uscode/text/5/7103","subs":["(a)(3)"],"by":{"2":"20"}},{"t":"usc","label":"11 U.S.C. § 510","url":"https://www.law.cornell.edu/uscode/text/11/510","subs":["(a)","(c)"],"by":{"2":"9, 9, 9"}},{"t":"usc","label":"11 U.S.C. § 522","url":"https://www.law.cornell.edu/uscode/text/11/522","subs":["(c)(1)"],"by":{"2":"9"}},{"t":"usc","label":"11 U.S.C. § 524","url":"https://www.law.cornell.edu/uscode/text/11/524","by":{"2":"8"}},{"t":"usc","label":"11 U.S.C. § 1141","url":"https://www.law.cornell.edu/uscode/text/11/1141","by":{"2":"8"}},{"t":"usc","label":"11 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/11/1227","by":{"2":"8"}},{"t":"usc","label":"11 U.S.C. § 1327","url":"https://www.law.cornell.edu/uscode/text/11/1327","by":{"2":"8"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(a)(2)"],"by":{"2":"9"}},{"t":"usc","label":"28 U.S.C. § 1491","url":"https://www.law.cornell.edu/uscode/text/28/1491","subs":["(a)(1)"],"by":{"2":"9"}},{"t":"usc","label":"28 U.S.C. § 2201","url":"https://www.law.cornell.edu/uscode/text/28/2201","by":{"2":"17"}},{"t":"usc","label":"28 U.S.C. § 2410","url":"https://www.law.cornell.edu/uscode/text/28/2410","subs":["(a)"],"by":{"2":"11"}}]};